diff --git a/src/Commands/Dir/Native/NativeMorphOSDirCommand.cs b/src/Commands/Dir/Native/NativeMorphOSDirCommand.cs
index a39da96..09007d2 100644
--- a/src/Commands/Dir/Native/NativeMorphOSDirCommand.cs
+++ b/src/Commands/Dir/Native/NativeMorphOSDirCommand.cs
@@ -123,7 +123,8 @@ public static class NativeMorphOSDirCommand
                     {
                         var ignored = default(NameRow);
                         ignored.Name = value;
-                        DOS.VPrintf("%c option ignored\n",
+                        // NameRow stores a long; plain %c consumes a word on Amiga DOS.
+                        DOS.VPrintf("%lc option ignored\n",
                             NameRow.AddressOf(ref ignored));
                     }
                 }
